'use client';

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import type { TouchEvent } from 'react';
import type { NocturneEvent } from '@/data/events';
import { events } from '@/data/events';
import { galleryImages } from '@/data/gallery';
import './Home.css';

type HomeProps = {
  initialDateKey: string;
};

type Tab = 'home' | 'past' | 'gallery' | 'contact';

const tabs: Tab[] = ['home', 'past', 'gallery', 'contact'];

const tabLabels: Record<Tab, string> = {
  home: 'HOME',
  past: 'PAST RAVES',
  gallery: 'GALLERY',
  contact: 'CONTACT',
};

function getMelbourneDateKey() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Australia/Melbourne',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());

  const part = (type: string) =>
    parts.find((item) => item.type === type)?.value ?? '';

  return `${part('year')}-${part('month')}-${part('day')}`;
}

function formatDate(date: string) {
  return new Intl.DateTimeFormat('en-AU', {
    timeZone: 'Australia/Melbourne',
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  }).format(new Date(`${date}T12:00:00Z`));
}

function EventArtwork({
  event,
  className = '',
}: {
  event: NocturneEvent;
  className?: string;
}) {
  return (
    <picture className={`nocturne-artwork ${className}`}>
      <source
        media="(max-width: 760px)"
        srcSet={event.portraitImage}
      />
      <img
        className="nocturne-artwork-image"
        src={event.bannerImage}
        alt={`${event.title} event artwork`}
      />
    </picture>
  );
}

function EventDetails({
  event,
  compact = false,
}: {
  event: NocturneEvent;
  compact?: boolean;
}) {
  return (
    <div className={compact ? 'nocturne-card-details' : 'nocturne-details'}>
      <p className="nocturne-event-date">{formatDate(event.date)}</p>
      <h2>{event.title}</h2>
      <p className="nocturne-venue">{event.venue}</p>

      {event.lineup.length > 0 && (
        <p className="nocturne-lineup">
          {event.lineup.join(' / ')}
        </p>
      )}
    </div>
  );
}

function TicketLink({ event }: { event: NocturneEvent }) {
  if (!event.ticketUrl) return null;

  return (
    <a
      className="nocturne-ticket"
      href={event.ticketUrl}
      target="_blank"
      rel="noopener noreferrer"
    >
      TICKETS <span aria-hidden="true">↗</span>
    </a>
  );
}

function EventCarousel({
  items,
  emptyMessage,
}: {
  items: NocturneEvent[];
  emptyMessage: string;
}) {
  const carouselRef = useRef<HTMLDivElement>(null);

  const moveCarousel = (direction: -1 | 1) => {
    const carousel = carouselRef.current;
    if (!carousel) return;

    const firstCard = carousel.querySelector<HTMLElement>(
      '.nocturne-event-card',
    );

    const distance = firstCard
      ? firstCard.offsetWidth + 16
      : carousel.clientWidth * 0.8;

    carousel.scrollBy({
      left: direction * distance,
      behavior: 'smooth',
    });
  };

  if (items.length === 0) {
    return <p className="nocturne-empty">{emptyMessage}</p>;
  }

  return (
    <div className="nocturne-carousel-wrap">
      <div className="nocturne-carousel-controls">
        <button
          type="button"
          onClick={() => moveCarousel(-1)}
          aria-label="Previous event"
        >
          ←
        </button>
        <button
          type="button"
          onClick={() => moveCarousel(1)}
          aria-label="Next event"
        >
          →
        </button>
      </div>

      <div className="nocturne-event-carousel" ref={carouselRef}>
        {items.map((event) => (
          <article className="nocturne-event-card" key={event.id}>
            <EventArtwork event={event} />

            <div className="nocturne-card-content">
              <EventDetails event={event} compact />
              <TicketLink event={event} />
            </div>
          </article>
        ))}
      </div>
    </div>
  );
}

export default function Home({ initialDateKey }: HomeProps) {
  const [todayKey, setTodayKey] = useState(initialDateKey);
  const [activeTab, setActiveTab] = useState<Tab>('home');
  const [featuredIndex, setFeaturedIndex] = useState(0);

  const touchStart = useRef<{ x: number; y: number } | null>(null);

  useEffect(() => {
    const updateDate = () => setTodayKey(getMelbourneDateKey());

    updateDate();

    const interval = window.setInterval(updateDate, 60_000);
    return () => window.clearInterval(interval);
  }, []);

  const upcomingEvents = useMemo(
    () =>
      events
        .filter((event) => event.date >= todayKey)
        .sort((a, b) => a.date.localeCompare(b.date)),
    [todayKey],
  );

  const pastEvents = useMemo(
    () =>
      events
        .filter((event) => event.date < todayKey)
        .sort((a, b) => b.date.localeCompare(a.date)),
    [todayKey],
  );

  useEffect(() => {
    setFeaturedIndex(0);
  }, [todayKey]);

  const safeFeaturedIndex =
    upcomingEvents.length > 0
      ? featuredIndex % upcomingEvents.length
      : 0;

  const featuredEvent = upcomingEvents[safeFeaturedIndex];

  const changeTab = useCallback((direction: -1 | 1) => {
    setActiveTab((current) => {
      const currentIndex = tabs.indexOf(current);
      const nextIndex =
        (currentIndex + direction + tabs.length) % tabs.length;

      return tabs[nextIndex];
    });
  }, []);

  const handleTouchStart = (event: TouchEvent<HTMLElement>) => {
    if (
      (event.target as HTMLElement).closest(
        '.nocturne-event-carousel, .nocturne-gallery-track, button, a',
      )
    ) {
      touchStart.current = null;
      return;
    }

    const touch = event.touches[0];
    touchStart.current = { x: touch.clientX, y: touch.clientY };
  };

  const handleTouchEnd = (event: TouchEvent<HTMLElement>) => {
    if (!touchStart.current) return;

    const touch = event.changedTouches[0];
    const deltaX = touch.clientX - touchStart.current.x;
    const deltaY = touch.clientY - touchStart.current.y;

    touchStart.current = null;

    if (
      Math.abs(deltaX) < 80 ||
      Math.abs(deltaX) < Math.abs(deltaY) * 1.25
    ) {
      return;
    }

    changeTab(deltaX < 0 ? 1 : -1);
  };

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key !== 'ArrowLeft' &&
        event.key !== 'ArrowRight'
      ) {
        return;
      }

      const target = event.target as HTMLElement | null;

      if (
        target?.closest(
          'a, button, input, textarea, select, [contenteditable="true"]',
        )
      ) {
        return;
      }

      changeTab(event.key === 'ArrowRight' ? 1 : -1);
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [changeTab]);

  const contactEmail = process.env.NEXT_PUBLIC_CONTACT_EMAIL;

  return (
    <main
      className="nocturne-app"
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      {/* Shared background video across every tab */}
      <video
        className="nocturne-background-video"
        autoPlay
        muted
        loop
        playsInline
        preload="metadata"
        poster="/img/bg.jpg"
        aria-hidden="true"
      >
        <source
          src="/video/nocturne-rave.mp4"
          type="video/mp4"
        />
      </video>

      <div className="nocturne-video-shade" aria-hidden="true" />

      <header className="nocturne-header">
        <button
          className="nocturne-wordmark"
          type="button"
          aria-label="Go to Home"
          onClick={() => setActiveTab('home')}
        >
          NOCTURNE<span>.</span>
        </button>

        <nav className="nocturne-tabs" aria-label="Main navigation">
          {tabs.map((tab, index) => (
            <button
              type="button"
              key={tab}
              className={activeTab === tab ? 'active' : ''}
              onClick={() => setActiveTab(tab)}
              aria-current={activeTab === tab ? 'page' : undefined}
            >
              <span className="nocturne-tab-number">
                0{index + 1}
              </span>
              {tabLabels[tab]}
            </button>
          ))}
        </nav>

        <span className="nocturne-location">MELBOURNE, AU</span>
      </header>

      <div className="nocturne-screen" key={activeTab}>
        {activeTab === 'home' && (
          <section className="nocturne-home-screen">
            {featuredEvent ? (
              <>
                <EventArtwork
                  event={featuredEvent}
                  className="nocturne-hero-artwork"
                />

                <div className="nocturne-home-content">
                  <p className="nocturne-kicker">
                    NEXT EVENT <span>—</span>{' '}
                    {String(safeFeaturedIndex + 1).padStart(2, '0')}
                    {' / '}
                    {String(upcomingEvents.length).padStart(2, '0')}
                  </p>

                  <EventDetails event={featuredEvent} />
                  <TicketLink event={featuredEvent} />

                  {upcomingEvents.length > 1 && (
                    <div className="nocturne-feature-controls">
                      <button
                        type="button"
                        aria-label="Previous upcoming event"
                        onClick={() =>
                          setFeaturedIndex(
                            (safeFeaturedIndex - 1 + upcomingEvents.length) %
                              upcomingEvents.length,
                          )
                        }
                      >
                        ←
                      </button>

                      <button
                        type="button"
                        aria-label="Next upcoming event"
                        onClick={() =>
                          setFeaturedIndex(
                            (safeFeaturedIndex + 1) % upcomingEvents.length,
                          )
                        }
                      >
                        →
                      </button>
                    </div>
                  )}
                </div>
              </>
            ) : (
              <div className="nocturne-no-event">
                <p className="nocturne-kicker">NO UPCOMING EVENTS</p>
                <h1>
                  NOTHING<br />
                  ANNOUNCED<span>.</span>
                </h1>
              </div>
            )}

            <p className="nocturne-swipe-hint">
              SWIPE LEFT / RIGHT TO EXPLORE
            </p>
          </section>
        )}

        {activeTab === 'past' && (
          <section className="nocturne-list-screen">
            <div className="nocturne-list-heading">
              <p className="nocturne-kicker">THE ARCHIVE</p>
              <h1>
                PAST RAVES<span>.</span>
              </h1>
              <p>Previous events.</p>
            </div>

            <EventCarousel
              items={pastEvents}
              emptyMessage="The archive is empty for now."
            />

            <p className="nocturne-swipe-hint">
              SWIPE LEFT / RIGHT TO EXPLORE
            </p>
          </section>
        )}

        {activeTab === 'gallery' && (
          <section className="nocturne-list-screen nocturne-gallery-screen">
            <div className="nocturne-list-heading">
              <p className="nocturne-kicker">ON THE FLOOR</p>
              <h1>
                GALLERY<span>.</span>
              </h1>
              <p>Through the lens.</p>
            </div>

            <div className="nocturne-gallery-track">
              {galleryImages.map((image) => (
                <figure
                  className="nocturne-gallery-image"
                  key={image.src}
                >
                  <img src={image.src} alt={image.alt} />
                </figure>
              ))}
            </div>

            <p className="nocturne-swipe-hint">
              SWIPE THROUGH THE GALLERY ↔
            </p>
          </section>
        )}

        {activeTab === 'contact' && (
          <section className="nocturne-contact-screen">
            <p className="nocturne-kicker">
              BOOKINGS · COLLABS · ENQUIRIES
            </p>

            <h1>
              GET IN<br />
              TOUCH<span>.</span>
            </h1>

            <div className="nocturne-contact-links">
              {contactEmail && (
                <a href={`mailto:${contactEmail}`}>
                  EMAIL <span>{contactEmail}</span> ↗
                </a>
              )}

              <a
                href="https://www.instagram.com/nocturneravers/"
                target="_blank"
                rel="noopener noreferrer"
              >
                INSTAGRAM <span>@nocturneravers</span> ↗
              </a>
            </div>
          </section>
        )}
      </div>

      <footer className="nocturne-footer">
        <span>NOCTURNE</span>
        <span>DRUM &amp; BASS</span>

        <div className="nocturne-footer-arrows">
          <button
            type="button"
            aria-label="Previous tab"
            onClick={() => changeTab(-1)}
          >
            ←
          </button>
          <button
            type="button"
            aria-label="Next tab"
            onClick={() => changeTab(1)}
          >
            →
          </button>
        </div>
      </footer>
    </main>
  );
}